import os
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from typing import Any
from urllib.parse import urlsplit

from fastapi import FastAPI, HTTPException, Query, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, field_validator

SCHEMA = """
CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
    tag TEXT NOT NULL,
    PRIMARY KEY (bookmark_id, tag)
);
CREATE INDEX IF NOT EXISTS idx_bookmark_tags_tag ON bookmark_tags(tag);
"""


def normalize_tag(tag: str) -> str:
    return tag.strip().lower()


def normalize_tags(tags: list[str] | None) -> list[str]:
    if not tags:
        return []
    return sorted({t for t in (normalize_tag(x) for x in tags) if t})


def valid_url(url: str) -> bool:
    if any(c.isspace() for c in url):
        return False
    try:
        parts = urlsplit(url)
        host = parts.hostname
    except ValueError:
        return False
    return parts.scheme in ("http", "https") and bool(host) and url.lower().startswith(
        ("http://", "https://")
    )


class BookmarkCreate(BaseModel):
    url: str
    title: str | None = None
    tags: list[str] | None = None

    @field_validator("url")
    @classmethod
    def check_url(cls, v: str) -> str:
        if not valid_url(v):
            raise ValueError("url must be a valid http(s) URL")
        return v


class BookmarkUpdate(BaseModel):
    model_config = ConfigDict(extra="allow")

    title: str | None = None
    tags: list[str] | None = None
    url: Any = None


def _contains(haystack: str | None, needle: str | None) -> int:
    if haystack is None or needle is None:
        return 0
    return int(needle.casefold() in haystack.casefold())


def create_app(db_path: str) -> FastAPI:
    app = FastAPI(title="Bookmarks API")

    def connect() -> sqlite3.Connection:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        conn.create_function("icontains", 2, _contains, deterministic=True)
        return conn

    @contextmanager
    def db():
        conn = connect()
        try:
            with conn:
                yield conn
        finally:
            conn.close()

    with db() as conn:
        conn.executescript(SCHEMA)

    def load(conn: sqlite3.Connection, bookmark_id: int) -> dict | None:
        row = conn.execute(
            "SELECT id, url, title, created_at FROM bookmarks WHERE id = ?",
            (bookmark_id,),
        ).fetchone()
        if row is None:
            return None
        return to_dict(conn, row)

    def to_dict(conn: sqlite3.Connection, row: sqlite3.Row) -> dict:
        tags = [
            r[0]
            for r in conn.execute(
                "SELECT tag FROM bookmark_tags WHERE bookmark_id = ? ORDER BY tag",
                (row["id"],),
            )
        ]
        return {
            "id": row["id"],
            "url": row["url"],
            "title": row["title"],
            "tags": tags,
            "created_at": row["created_at"],
        }

    def set_tags(conn: sqlite3.Connection, bookmark_id: int, tags: list[str]) -> None:
        conn.execute("DELETE FROM bookmark_tags WHERE bookmark_id = ?", (bookmark_id,))
        conn.executemany(
            "INSERT INTO bookmark_tags (bookmark_id, tag) VALUES (?, ?)",
            [(bookmark_id, t) for t in tags],
        )

    def not_found() -> JSONResponse:
        return JSONResponse(status_code=404, content={"detail": "not found"})

    @app.get("/health")
    def health():
        return {"status": "ok"}

    @app.post("/bookmarks", status_code=201)
    def create_bookmark(body: BookmarkCreate):
        title = (body.title or "").strip() or body.url
        tags = normalize_tags(body.tags)
        created_at = datetime.now(timezone.utc).isoformat()
        with db() as conn:
            try:
                cur = conn.execute(
                    "INSERT INTO bookmarks (url, title, created_at) VALUES (?, ?, ?)",
                    (body.url, title, created_at),
                )
            except sqlite3.IntegrityError:
                return JSONResponse(status_code=409, content={"detail": "duplicate url"})
            bookmark_id = cur.lastrowid
            set_tags(conn, bookmark_id, tags)
            return load(conn, bookmark_id)

    @app.get("/bookmarks")
    def list_bookmarks(
        tag: str | None = None,
        q: str | None = None,
        limit: int = Query(20, ge=1, le=100),
        offset: int = Query(0, ge=0),
    ):
        sql = "SELECT id, url, title, created_at FROM bookmarks b"
        where: list[str] = []
        params: list[Any] = []
        if tag is not None:
            where.append(
                "EXISTS (SELECT 1 FROM bookmark_tags t WHERE t.bookmark_id = b.id AND t.tag = ?)"
            )
            params.append(normalize_tag(tag))
        if q is not None and q != "":
            where.append("(icontains(b.title, ?) OR icontains(b.url, ?))")
            params.extend([q, q])
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY b.id DESC LIMIT ? OFFSET ?"
        params.extend([limit, offset])
        with db() as conn:
            rows = conn.execute(sql, params).fetchall()
            return [to_dict(conn, r) for r in rows]

    @app.get("/bookmarks/{bookmark_id}")
    def get_bookmark(bookmark_id: int):
        with db() as conn:
            bm = load(conn, bookmark_id)
        if bm is None:
            return not_found()
        return bm

    @app.patch("/bookmarks/{bookmark_id}")
    def update_bookmark(bookmark_id: int, body: BookmarkUpdate):
        fields = body.model_fields_set
        if "url" in fields:
            raise HTTPException(status_code=422, detail="url cannot be changed")
        with db() as conn:
            bm = load(conn, bookmark_id)
            if bm is None:
                return not_found()
            if "title" in fields:
                title = (body.title or "").strip() or bm["url"]
                conn.execute(
                    "UPDATE bookmarks SET title = ? WHERE id = ?", (title, bookmark_id)
                )
            if "tags" in fields:
                set_tags(conn, bookmark_id, normalize_tags(body.tags))
            return load(conn, bookmark_id)

    @app.delete("/bookmarks/{bookmark_id}", status_code=204)
    def delete_bookmark(bookmark_id: int):
        with db() as conn:
            cur = conn.execute("DELETE FROM bookmarks WHERE id = ?", (bookmark_id,))
            if cur.rowcount == 0:
                return not_found()
        return Response(status_code=204)

    @app.get("/tags")
    def list_tags():
        with db() as conn:
            rows = conn.execute(
                "SELECT tag, COUNT(*) AS n FROM bookmark_tags GROUP BY tag ORDER BY tag"
            ).fetchall()
        return [{"name": r["tag"], "count": r["n"]} for r in rows]

    return app


app = create_app(os.environ.get("BOOKMARKS_DB", "bookmarks.db"))
