def _normalize_tags(tags: Any) -> Optional[list[str]]:
    """Return normalized list, or None if invalid."""
    if tags is None:
        return []
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        return None
    return sorted({_normalize_tag(t) for t in tags if _normalize_tag(t)})


def _normalize_title(title: Any, url: str) -> Optional[str]:
    """Return normalized title, or None if invalid type."""
    if title is None:
        return url
    if not isinstance(title, str):
        return None
    title = title.strip()
    return title or url


SCHEMA = """
CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
    tag TEXT NOT NULL,
    PRIMARY KEY (bookmark_id, tag)
);
CREATE INDEX IF NOT EXISTS idx_bookmark_tags_tag ON bookmark_tags(tag);
"""


def create_app(db_path: str) -> FastAPI:
    def connect() -> sqlite3.Connection:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        return conn

    with connect() as conn:
        conn.executescript(SCHEMA)
    conn.close()

    def fetch(conn: sqlite3.Connection, bid: int) -> Optional[dict]:
        row = conn.execute("SELECT * FROM bookmarks WHERE id = ?", (bid,)).fetchone()
        if row is None:
            return None
        tags = [
            r["tag"]
            for r in conn.execute(
                "SELECT tag FROM bookmark_tags WHERE bookmark_id = ? ORDER BY tag", (bid,)
            )
        ]
        return {
            "id": row["id"],
            "url": row["url"],
            "title": row["title"],
            "tags": tags,
            "created_at": row["created_at"],
        }

    def set_tags(conn: sqlite3.Connection, bid: int, tags: list[str]) -> None:
        conn.execute("DELETE FROM bookmark_tags WHERE bookmark_id = ?", (bid,))
        conn.executemany(
            "INSERT INTO bookmark_tags (bookmark_id, tag) VALUES (?, ?)",
            [(bid, t) for t in tags],
        )

    app = FastAPI(title="Bookmarks API")

    @app.get("/health")
    def health():
        return {"status": "ok"}

    @app.post("/bookmarks", status_code=201)
    def create_bookmark(body: dict = Body(...)):
        url = body.get("url")
        if not _is_valid_url(url):
            return _err(422, "invalid url")
        title = _normalize_title(body.get("title"), url)
        if title is None:
            return _err(422, "invalid title")
        tags = _normalize_tags(body.get("tags"))
        if tags is None:
            return _err(422, "invalid tags")
        created_at = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        conn = connect()
        try:
            with conn:
                try:
                    cur = conn.execute(
                        "INSERT INTO bookmarks (url, title, created_at) VALUES (?, ?, ?)",
                        (url, title, created_at),
                    )
                except sqlite3.IntegrityError:
                    return _err(409, "duplicate url")
                set_tags(conn, cur.lastrowid, tags)
            return fetch(conn, cur.lastrowid)
        finally:
            conn.close()

    @app.get("/bookmarks")
    def list_bookmarks(
        tag: Optional[str] = None,
        q: Optional[str] = None,
        limit: int = Query(20, ge=1, le=100),
        offset: int = Query(0, ge=0),
    ):
        where, params = [], []
        if tag is not None:
            where.append(
                "id IN (SELECT bookmark_id FROM bookmark_tags WHERE tag = ?)"
            )
            params.append(_normalize_tag(tag))
        if q is not None and q != "":
            where.append("(instr(lower(title), lower(?)) > 0 OR instr(lower(url), lower(?)) > 0)")
            params += [q, q]
        sql = "SELECT id FROM bookmarks"
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY id DESC LIMIT ? OFFSET ?"
        params += [limit, offset]
        conn = connect()
        try:
            ids = [r["id"] for r in conn.execute(sql, params)]
            return [fetch(conn, i) for i in ids]
        finally:
            conn.close()

    @app.get("/bookmarks/{bookmark_id}")
    def get_bookmark(bookmark_id: int):
        conn = connect()
        try:
            bm = fetch(conn, bookmark_id)
            return bm if bm else _err(404, "not found")
        finally:
            conn.close()

    @app.patch("/bookmarks/{bookmark_id}")
    def update_bookmark(bookmark_id: int, body: dict = Body(...)):
        if "url" in body:
            return _err(422, "url cannot be changed")
        conn = connect()
        try:
            bm = fetch(conn, bookmark_id)
            if bm is None:
                return _err(404, "not found")
            title = bm["title"]
            if "title" in body:
                title = _normalize_title(body["title"], bm["url"])
                if title is None:
                    return _err(422, "invalid title")
            tags = None
            if "tags" in body:
                tags = _normalize_tags(body["tags"])
                if tags is None:
                    return _err(422, "invalid tags")
            with conn:
                conn.execute(
                    "UPDATE bookmarks SET title = ? WHERE id = ?", (title, bookmark_id)
                )
                if tags is not None:
                    set_tags(conn, bookmark_id, tags)
            return fetch(conn, bookmark_id)
        finally:
            conn.close()

    @app.delete("/bookmarks/{bookmark_id}", status_code=204)
    def delete_bookmark(bookmark_id: int):
        conn = connect()
        try:
            with conn:
                cur = conn.execute("DELETE FROM bookmarks WHERE id = ?", (bookmark_id,))
            if cur.rowcount == 0:
                return _err(404, "not found")
            return Response(status_code=204)
        finally:
            conn.close()

    @app.get("/tags")
    def list_tags():
        conn = connect()
        try:
            rows = conn.execute(
                "SELECT tag, COUNT(*) AS c FROM bookmark_tags GROUP BY tag ORDER BY tag"
            ).fetchall()
            return [{"name": r["tag"], "count": r["c"]} for r in rows]
        finally:
            conn.close()

    return app


